import { GoogleGenAI, Type, Modality } from "@google/genai";
import { TrendReport } from "../types";

// Note: Exclusive source of API_KEY is process.env.API_KEY
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Fetches elite styling advice based on user mood and objective using Gemini 3 Flash.
 */
export const getStylingAdvice = async (mood: string, occasion: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Analyze user mood '${mood}' and objective '${occasion}'. Provide an elite, multidisciplinary styling verdict for the high-fashion streetwear platform 'Closet Kraze'.`,
    config: {
      systemInstruction: "You are a Senior Style Architect for Closet Kraze. Your tone is confident, modern, and provocative. Keep answers concise and high-impact. Focus on materials, silhouette weight, and status signaling.",
    },
  });

  return response.text || "Neural style sensors are jammed. Maintain baseline silhouette.";
};

/**
 * Fetches market trend intelligence for a specific archetype using Gemini 3 Flash and JSON schema.
 */
export const getTrendIntelligence = async (archetype: string): Promise<TrendReport> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Provide a detailed fashion market trend intelligence report for the '${archetype}' archetype in Sector_01 for the current lunar cycle.`,
    config: {
      systemInstruction: "You are a market oracle for Closet Kraze. Return trend intel in JSON format. Be avant-garde and analytical.",
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          text: {
            type: Type.STRING,
            description: 'The market intelligence report text.',
          },
          sources: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                uri: { type: Type.STRING },
              },
              required: ["title", "uri"],
            },
            description: 'Analytical sources supporting the report.',
          },
        },
        required: ["text", "sources"],
      },
    },
  });

  try {
    const data = JSON.parse(response.text || "{}");
    return {
      text: data.text || "Market Anomaly detected. Demand surge imminent.",
      sources: data.sources || [
        { title: "Neo Tokyo Market Feed", uri: "https://archives.closetkraze.nt/trends" }
      ]
    };
  } catch (e) {
    console.error("Failed to parse trend report:", e);
    return {
      text: "Global signals indicate a mass shift toward Minimalist Void aesthetics. Silhouette density is dropping as 'Zero Point' styling becomes the new authority standard.",
      sources: [
        { title: "Neo Tokyo Market Feed", uri: "https://archives.closetkraze.nt/trends" },
        { title: "Neural Style Weekly", uri: "https://vibe.circuit.net/intel" }
      ]
    };
  }
};

/**
 * Materializes an outfit blueprint using Gemini Flash Image or Pro Image for high-fi requests.
 */
export const generateDreamOutfit = async (description: string, highFi: boolean = false) => {
  const model = highFi ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';
  const response = await ai.models.generateContent({
    model: model,
    contents: {
      parts: [
        {
          text: `Materialize a high-fashion editorial silhouette blueprint for Closet Kraze. Subject: ${description}. Technical streetwear, luxury avant-garde aesthetic, moody studio lighting, ${highFi ? '4k' : '8k'} resolution, cinematic composition.`,
        },
      ],
    },
    config: {
      imageConfig: {
        aspectRatio: "3:4",
        imageSize: highFi ? "2K" : "1K"
      }
    }
  });

  if (response.candidates?.[0]?.content?.parts) {
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        const base64EncodeString: string = part.inlineData.data;
        return `data:image/png;base64,${base64EncodeString}`;
      }
    }
  }

  return "https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?auto=format&fit=crop&q=80&w=800";
};

/**
 * Connects to the Live Neural Concierge using Gemini 2.5 Flash Native Audio.
 */
export const connectToConcierge = (userContext: any, callbacks: any) => {
  const liveAi = new GoogleGenAI({ apiKey: process.env.API_KEY });
  return liveAi.live.connect({
    model: 'gemini-2.5-flash-native-audio-preview-12-2025',
    callbacks,
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
      },
      systemInstruction: `You are the Closet Kraze Neural Concierge. Your tone is elite, clinical, and authoritative. 
      The user's current rank is ${userContext.rankTier}. Their identity is ${userContext.handle}.
      Guide them through the circuit. Use fashion terminology like 'silhouette', 'archive', 'sector', and 'velocity heat'.
      Address them by their status. If they ask about buying, emphasize scarcity and status acquisition.`,
    },
  });
};

import React, { useState, useRef, useEffect } from 'react';
import { connectToConcierge } from '../services/geminiService';
import { LiveServerMessage } from '@google/genai';

interface ConciergeLiveProps {
  userContext: {
    handle: string;
    rankTier: string;
    rep: number;
  };
}

const ConciergeLive: React.FC<ConciergeLiveProps> = ({ userContext }) => {
  const [isActive, setIsActive] = useState(false);
  const [isConnecting, setIsConnecting] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [visualVolume, setVisualVolume] = useState(0);

  const audioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionPromiseRef = useRef<Promise<any> | null>(null);

  const startSession = async () => {
    setIsConnecting(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const inputContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });

      const sessionPromise = connectToConcierge(userContext, {
        onopen: () => {
          setIsConnecting(false);
          setIsActive(true);
          setIsListening(true);

          const source = inputContext.createMediaStreamSource(stream);
          const processor = inputContext.createScriptProcessor(4096, 1, 1);

          processor.onaudioprocess = (e) => {
            const inputData = e.inputBuffer.getChannelData(0);
            const pcmBlob = createPcmBlob(inputData);

            // Visualizer feedback
            const sum = inputData.reduce((a, b) => a + Math.abs(b), 0);
            setVisualVolume(sum / inputData.length);

            sessionPromise.then(session => {
              session.sendRealtimeInput({ media: pcmBlob });
            });
          };

          source.connect(processor);
          processor.connect(inputContext.destination);
        },
        onmessage: async (message: LiveServerMessage) => {
          const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64Audio && audioContextRef.current) {
            const ctx = audioContextRef.current;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const audioBuffer = await decodePcm(base64Audio, ctx);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += audioBuffer.duration;
            sourcesRef.current.add(source);
            source.onended = () => sourcesRef.current.delete(source);
          }

          if (message.serverContent?.interrupted) {
            sourcesRef.current.forEach(s => s.stop());
            sourcesRef.current.clear();
            nextStartTimeRef.current = 0;
          }
        },
        onerror: (e: any) => console.error("Concierge Error:", e),
        onclose: () => stopSession(),
      });

      sessionPromiseRef.current = sessionPromise;
    } catch (err) {
      console.error("Failed to start concierge:", err);
      setIsConnecting(false);
    }
  };

  const stopSession = () => {
    setIsActive(false);
    setIsListening(false);
    setIsConnecting(false);
    sourcesRef.current.forEach(s => s.stop());
    sessionPromiseRef.current?.then(s => s.close());
    sessionPromiseRef.current = null;
  };

  const createPcmBlob = (data: Float32Array) => {
    const int16 = new Int16Array(data.length);
    for (let i = 0; i < data.length; i++) int16[i] = data[i] * 32768;
    const binary = String.fromCharCode(...new Uint8Array(int16.buffer));
    return { data: btoa(binary), mimeType: 'audio/pcm;rate=16000' };
  };

  const decodePcm = async (base64: string, ctx: AudioContext) => {
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    const dataInt16 = new Int16Array(bytes.buffer);
    const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
    const channelData = buffer.getChannelData(0);
    for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
    return buffer;
  };

  return (
    <div className="fixed bottom-32 right-8 z-[250] flex flex-col items-end gap-4">
      {isActive && (
        <div className="bg-black/80 backdrop-blur-2xl border border-[#EC4899]/30 p-6 rounded-[2.5rem] shadow-2xl animate-in slide-in-from-bottom-4 duration-500 mb-2 max-w-[200px] text-center">
          <div className="flex justify-center gap-1 h-8 items-end mb-4">
            {[1, 2, 3, 4, 5].map(i => (
              <div 
                key={i} 
                className="w-1 bg-[#EC4899] rounded-full transition-all duration-100" 
                style={{ height: `${Math.max(10, visualVolume * 300 * (1 + Math.random()))}%` }}
              />
            ))}
          </div>
          <p className="text-[8px] font-black text-[#EC4899] uppercase tracking-widest animate-pulse">Neural Link Active</p>
        </div>
      )}

      <button
        onClick={isActive ? stopSession : startSession}
        disabled={isConnecting}
        className={`w-20 h-20 rounded-[2.2rem] flex items-center justify-center text-3xl shadow-2xl transition-all duration-500 relative group overflow-hidden border ${
          isActive 
          ? 'bg-[#EC4899] border-[#EC4899] text-white scale-110' 
          : 'bg-zinc-900 border-white/10 text-zinc-500 hover:border-[#EC4899]/50 hover:text-white'
        }`}
      >
        {isConnecting ? (
          <div className="w-8 h-8 border-2 border-white/20 border-t-white rounded-full animate-spin" />
        ) : isActive ? (
          <span className="relative z-10">⏹</span>
        ) : (
          <span className="relative z-10">🎙️</span>
        )}

        {isActive && (
          <div className="absolute inset-0 bg-white/20 animate-ping rounded-full" />
        )}

        <div className="absolute inset-0 bg-gradient-to-tr from-[#EC4899]/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
      </button>

      {!isActive && !isConnecting && (
        <span className="text-[7px] font-black text-zinc-600 uppercase tracking-[0.4em] mr-2">Concierge_Uplink</span>
      )}
    </div>
  );
};

export default ConciergeLive;

import React, { useState, useEffect } from 'react';
