      let i = 0;
      interval = setInterval(() => {
        setImageLoadingText(texts[i % texts.length]);
        i++;
      }, 700);
    }
    return () => clearInterval(interval);
  }, [isGeneratingImage]);

  const handleConsult = async () => {
    if (!mood || !occasion) return;
    setIsLoadingAdvice(true);
