import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import BottomNav from './components/BottomNav';
import ProductDetail from './components/ProductDetail';
import CartDrawer from './components/CartDrawer';
import NotificationCenter from './components/NotificationCenter';
import Lobby from './components/HomeLobby';
import FamousProducts from './components/FamousProducts';
import TryOn from './components/TryOn';
import Bundles from './components/Bundles';
import OutfitBuilder from './components/OutfitBuilder';
import Categories from './components/Categories';
import FlashSales from './components/FlashSales';
import Profile from './components/Profile';
import WishlistView from './components/WishlistView';
import CategoryPanel from './components/CategoryPanel';
import SocialProofPopup from './components/SocialProofPopup';
import AdminPanel from './components/AdminPanel';
import SupplierDashboard from './components/SupplierDashboard';
import CheckoutView from './components/CheckoutView';
import AdminLogin from './components/AdminLogin';
import SupplierLogin from './components/SupplierLogin';
import RoleSelection from './components/RoleSelection';
import TrendIntelligence from './components/TrendIntelligence';
import ContactPanel from './components/ContactPanel';
import GameShowroom from './components/GameShowroom';
import PayForMe from './components/PayForMe';
import Tutorial from './components/Tutorial';
import LandingScreen from './components/LandingScreen';
import ConciergeLive from './components/ConciergeLive';
import { EXTENDED_PRODUCTS, MOCK_BUNDLES } from './mockData';
import { USER_ACHIEVEMENTS } from './data/extendedMock';
import { databaseService } from './services/databaseService';
import { getCurrentRank } from './data/rankingSystem';
import { Product, CartItem, Page, ViewState, UserStats, Bundle, Category, Achievement, Notification, PromoCode } from './types';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
    return localStorage.getItem('cc-auth-token') === 'true';
  });
  const [showAuthModal, setShowAuthModal] = useState<boolean>(!isAuthenticated);
  const [showTutorial, setShowTutorial] = useState<boolean>(false);

  const [currentView, setCurrentView] = useState<ViewState>(ViewState.LOBBY);
  const [activeSupplierId, setActiveSupplierId] = useState<string | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('closet-kraze-cart');
    return saved ? JSON.parse(saved) : [];
  });
  const [wishlist, setWishlist] = useState<string[]>(() => {
    const saved = localStorage.getItem('closet-kraze-wishlist');
    return saved ? JSON.parse(saved) : [];
  });
  const [achievements, setAchievements] = useState<Achievement[]>(() => {
    const saved = localStorage.getItem('closet-kraze-achievements');
    return saved ? JSON.parse(saved) : USER_ACHIEVEMENTS;
  });
  const [notifications, setNotifications] = useState<Notification[]>([]);

  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isNotificationOpen, setIsNotificationOpen] = useState(false);
  const [isCategoryPanelOpen, setIsCategoryPanelOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<Category>('All');
  const [timeLeft, setTimeLeft] = useState(300);

  const [rep, setRep] = useState<number>(() => {
    const saved = localStorage.getItem('cc-user-rep');
    return saved ? Number(saved) : 8500;
  });

  const [handle, setHandle] = useState<string>(() => {
    return localStorage.getItem('cc-user-handle') || 'Anonymous';
  });

  const [activePromo, setActivePromo] = useState<PromoCode | null>(null);
  const [surgeTimerEnd, setSurgeTimerEnd] = useState<number | null>(() => {
    const saved = localStorage.getItem('cc-surge-timer');
    return saved ? Number(saved) : null;
  });

  const [stats, setStats] = useState<UserStats>(() => {
    const saved = localStorage.getItem('closet-kraze-stats');
    return saved ? JSON.parse(saved) : {
      dailyGameAttempts: 3,
      lastGameReset: new Date().toDateString(),
      quests: [
        { id: 'q1', title: 'Analyze Velocity Heat', rewardREP: 100, icon: '🔥', completed: false },
        { id: 'q2', title: 'Refine Identity', rewardREP: 150, icon: '🎨', completed: false }
      ],
      selectedPath: 'CYBER',
      aiTryOnsUsedToday: 0
    };
  });

  const currentRank = getCurrentRank(rep);
  const balances = { coins: 4250, gems: 120, rep: rep };

  useEffect(() => {
    localStorage.setItem('closet-kraze-cart', JSON.stringify(cart));
    if (cart.length === 0) {
      setSurgeTimerEnd(null);
      localStorage.removeItem('cc-surge-timer');
    }
  }, [cart]);

  useEffect(() => {
    localStorage.setItem('cc-user-rep', rep.toString());
  }, [rep]);

  useEffect(() => {
    const interval = setInterval(() => {
      setNotifications(databaseService.getGlobalNotifications());
    }, 5000);
    setNotifications(databaseService.getGlobalNotifications());
    return () => clearInterval(interval);
  }, []);

  const requireAuth = (action: () => void) => {
    if (!isAuthenticated) {
      setShowAuthModal(true);
    } else {
      action();
    }
  };

  const addToCart = (product: Product, selectedSize?: string) => {
    requireAuth(() => {
      if (!surgeTimerEnd || Date.now() > surgeTimerEnd) {
        const newEnd = Date.now() + (300 * 1000);
        setSurgeTimerEnd(newEnd);
      }
      setCart(prev => {
        const existing = prev.find(item => item.id === product.id && item.selectedSize === selectedSize);
        if (existing) return prev.map(i => (i.id === product.id && i.selectedSize === selectedSize) ? { ...i, quantity: i.quantity + 1 } : i);
        return [...prev, { ...product, quantity: 1, selectedSize }];
      });
      setIsCartOpen(true);
    });
  };

  const toggleWishlist = (product: Product) => {
    requireAuth(() => {
      setWishlist(prev => 
        prev.includes(product.id) 
          ? prev.filter(id => id !== product.id) 
          : [...prev, product.id]
      );
    });
  };

  const handleMarkRead = (id: string) => {
    const updated = notifications.map(n => n.id === id ? { ...n, read: true } : n);
    setNotifications(updated);
    databaseService.updateNotifications(updated);
  };

  const handleMarkAllRead = () => {
    const updated = notifications.map(n => ({ ...n, read: true }));
    setNotifications(updated);
    databaseService.updateNotifications(updated);
  };

  const handleNavigateView = (view: ViewState) => {
    setCurrentView(view);
  };

  const handleAdminSuccess = (role: 'ADMIN' | 'SUPPLIER', id?: string) => {
    setShowAuthModal(false);
    if (role === 'ADMIN') {
      setCurrentView(ViewState.ADMIN);
    } else {
      setActiveSupplierId(id || 'sup1');
      setCurrentView(ViewState.SUPPLIER_DASHBOARD);
    }
  };

  const handleClearCart = () => {
    setCart([]);
    setSurgeTimerEnd(null);
    localStorage.removeItem('cc-surge-timer');
  };

  const handleTutorialComplete = () => {
    setShowTutorial(false);
    localStorage.setItem('cc-tutorial-complete', 'true');
    setCurrentView(ViewState.LOBBY);
  };

  const handleLoginComplete = (archetype: string, isNewUser: boolean) => {
    setStats(prev => ({...prev, selectedPath: archetype}));
    setIsAuthenticated(true);
    localStorage.setItem('cc-auth-token', 'true');
    setShowAuthModal(false);

    // Only show tutorial if they are a newly registered user
    if (isNewUser) {
      const hasCompleted = localStorage.getItem('cc-tutorial-complete') === 'true';
      if (!hasCompleted) {
        setShowTutorial(true);
      }
    }
  };

  const wishlistProducts = EXTENDED_PRODUCTS.filter(p => wishlist.includes(p.id));

  const renderView = () => {
    switch (currentView) {
      case ViewState.LOBBY:
        return (
          <Lobby 
            products={EXTENDED_PRODUCTS} 
            stats={stats} 
            wishlist={wishlist}
            onNavigate={handleNavigateView} 
            onAddToCart={(pId) => {
              const p = EXTENDED_PRODUCTS.find(x => x.id === pId);
              if (p) addToCart(p, p.sizes?.[0]);
            }} 
            onToggleWishlist={toggleWishlist}
            onProductClick={setSelectedProduct}
            onCompleteQuest={(qId) => {
              setStats(prev => {
                const quest = prev.quests.find(q => q.id === qId);
                if (quest && !quest.completed) {
                  setRep(r => r + quest.rewardREP);
                  return { ...prev, quests: prev.quests.map(q => q.id === qId ? { ...q, completed: true } : q) };
                }
                return prev;
              });
            }}
          />
        );
      case ViewState.FAMOUS:
        return (
          <FamousProducts 
            products={selectedCategory === 'All' ? EXTENDED_PRODUCTS : EXTENDED_PRODUCTS.filter(p => p.category === selectedCategory)} 
            wishlist={wishlist}
            onProductClick={setSelectedProduct} 
            onAddToCart={(p) => addToCart(p, p.sizes?.[0])}
            onToggleWishlist={toggleWishlist}
          />
        );
      case ViewState.TRY_ON: 
        return <TryOn rank={currentRank} stats={stats} onUsed={() => setStats(s => ({...s, aiTryOnsUsedToday: s.aiTryOnsUsedToday + 1}))} />;
      case ViewState.BUNDLES: 
        return <Bundles bundles={MOCK_BUNDLES} onAddBundle={(b) => b.products.forEach(p => addToCart(p, p.sizes?.[0]))} />;
      case ViewState.CATEGORIES: return <Categories onSelectCategory={setSelectedCategory} onNavigate={handleNavigateView} />;
      case ViewState.FLASH: return <FlashSales onAddToCart={(p) => addToCart(p, p.sizes?.[0])} />;
      case ViewState.PROFILE: return <Profile stats={stats} rep={rep} onNavigate={handleNavigateView} onLogout={() => { setIsAuthenticated(false); localStorage.removeItem('cc-auth-token'); setShowAuthModal(true); }} onApplyPromo={setActivePromo} activePromo={activePromo} />;
      case ViewState.WISHLIST: return <WishlistView products={EXTENDED_PRODUCTS} wishlistIds={wishlist} onAddToCart={(p) => addToCart(p, p.sizes?.[0])} onToggleWishlist={toggleWishlist} onProductClick={setSelectedProduct} onNavigate={handleNavigateView} rank={currentRank} />;
      case ViewState.TRENDS: return <TrendIntelligence stats={stats} />;
      case ViewState.CONTACT: return <ContactPanel />;
      case ViewState.GAME_SHOWROOM: return <GameShowroom attemptsRemaining={stats.dailyGameAttempts} onPlay={() => setStats(s => ({...s, dailyGameAttempts: s.dailyGameAttempts - 1}))} onWin={(r) => { setRep(prev => prev + 50); alert(`Reward Unlocked: ${r} + 50 REP`); }} />;
      case ViewState.PAY_FOR_ME: return <PayForMe rank={currentRank} wishlistProducts={wishlistProducts} onCompleteAcquisition={(p) => { setRep(r => r + 500); alert(`${p.name} acquired via Sponsorship Protocol!`); }} />;
      case ViewState.ROLE_SELECTION: return <RoleSelection onSelect={(role) => setCurrentView(role === 'ADMIN' ? ViewState.ADMIN_LOGIN : ViewState.SUPPLIER_LOGIN)} onCancel={() => setCurrentView(ViewState.LOBBY)} />;
      case ViewState.ADMIN_LOGIN: return <AdminLogin onSuccess={handleAdminSuccess} onCancel={() => setCurrentView(ViewState.ROLE_SELECTION)} />;
      case ViewState.SUPPLIER_LOGIN: return <SupplierLogin onSuccess={(id) => handleAdminSuccess('SUPPLIER', id)} onCancel={() => setCurrentView(ViewState.ROLE_SELECTION)} />;
      case ViewState.ADMIN: return <AdminPanel onExit={() => setCurrentView(ViewState.LOBBY)} onNavigate={handleNavigateView} />;
      case ViewState.SUPPLIER_DASHBOARD: return <SupplierDashboard supplierId={activeSupplierId || 'sup1'} onLogout={() => setCurrentView(ViewState.LOBBY)} />;
      case ViewState.CHECKOUT: return <CheckoutView items={cart} onComplete={() => { handleClearCart(); setRep(prev => prev + 250); }} onCancel={() => setCurrentView(ViewState.LOBBY)} balances={balances} activePromo={activePromo} />;
      default: return <Lobby products={EXTENDED_PRODUCTS} stats={stats} wishlist={wishlist} onNavigate={handleNavigateView} onAddToCart={() => {}} onToggleWishlist={() => {}} onProductClick={setSelectedProduct} onCompleteQuest={() => {}} />;
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-[#FAFAFA] flex flex-col font-sans">
      <Header 
        cartCount={cart.reduce((a, b) => a + b.quantity, 0)} 
        wishlistCount={wishlist.length}
        notificationCount={notifications.filter(n => !n.read).length}
        stats={stats}
        onCartOpen={() => setIsCartOpen(true)}
        onNotificationOpen={() => setIsNotificationOpen(true)}
        onNavigatePage={(p) => handleNavigateView(p === Page.HOME ? ViewState.LOBBY : ViewState.FAMOUS)}
        onNavigateView={handleNavigateView}
        currentPage={currentView === ViewState.LOBBY ? Page.HOME : Page.SHOP}
        currentView={currentView}
        dropTime={timeLeft}
        onOpenCategories={() => setIsCategoryPanelOpen(true)}
      />
      <main className="pt-24 flex-1">{renderView()}</main>
      <BottomNav currentView={currentView} onNavigate={handleNavigateView} onOpenCategories={() => setIsCategoryPanelOpen(true)} />

      <CartDrawer 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        items={cart} 
        onRemove={(id) => setCart(prev => prev.filter(i => i.id !== id))} 
        onUpdateQuantity={(id, d) => setCart(prev => prev.map(i => i.id === id ? {...i, quantity: Math.max(1, i.quantity + d)} : i))} 
        onClear={handleClearCart}
        onNavigate={handleNavigateView}
        surgeTimerEnd={surgeTimerEnd}
        activePromo={activePromo}
        rank={currentRank}
      />

      <NotificationCenter 
        isOpen={isNotificationOpen} 
        onClose={() => setIsNotificationOpen(false)} 
        notifications={notifications} 
        onMarkRead={handleMarkRead}
        onMarkAllRead={handleMarkAllRead}
      />

      <CategoryPanel isOpen={isCategoryPanelOpen} onClose={() => setIsCategoryPanelOpen(false)} onSelectCategory={setSelectedCategory} onNavigate={handleNavigateView} activeCategory={selectedCategory} products={EXTENDED_PRODUCTS} onProductSelect={setSelectedProduct} />
      <SocialProofPopup />

      {isAuthenticated && (
        <ConciergeLive userContext={{ handle, rankTier: currentRank.tier, rep }} />
      )}

      {selectedProduct && (
        <ProductDetail 
          product={selectedProduct} 
          stats={stats} 
          allProducts={EXTENDED_PRODUCTS}
          onClose={() => setSelectedProduct(null)} 
          onAddToCart={addToCart} 
          onUpdateSynergy={() => {}} 
          onToggleWishlist={toggleWishlist} 
          onProductClick={setSelectedProduct}
          isInWishlist={wishlist.includes(selectedProduct.id)} 
          rank={currentRank}
        />
      )}

      {showAuthModal && (
        <LandingScreen 
          onComplete={(arch, isNew) => {
            setHandle('User_' + Math.floor(Math.random()*1000));
            handleLoginComplete(arch, isNew);
          }} 
          onAdminAccess={() => {
            setShowAuthModal(false);
            setCurrentView(ViewState.ROLE_SELECTION);
          }}
          onClose={() => setShowAuthModal(false)}
        />
      )}

      {showTutorial && (
        <Tutorial 
          onComplete={handleTutorialComplete}
          onNavigate={(view) => setCurrentView(view)}
        />
      )}
    </div>
  );
};

export default App;

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { TrendReport } from "../types";

// The exclusive source of API_KEY is process.env.API_KEY
// We initialize a new instance per call in dynamic scenarios to ensure the latest selected key is used.

/**
 * Fetches elite styling advice based on user mood and objective.
 */
export const getStylingAdvice = async (mood: string, occasion: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Analyze user mood '${mood}' and objective '${occasion}'. Provide an elite, provocative styling verdict for 'Closet Kraze'.`,
    config: {
      systemInstruction: "You are a Senior Style Architect. Your tone is confident, modern, and clinical. Focus on silhouette weight and status signaling. Max 50 words.",
    },
  });

  return response.text || "Maintain baseline silhouette. Neural sensors offline.";
};

/**
 * Fetches market trend intelligence using Gemini 3 Pro for complex reasoning.
 */
export const getTrendIntelligence = async (archetype: string): Promise<TrendReport> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Provide an analytical fashion market intelligence report for the '${archetype}' archetype in Sector_01 for the current lunar cycle.`,
    config: {
      systemInstruction: "You are a market oracle. Return trend intel in JSON format. Be avant-garde and analytical. Focus on material scarcity and aesthetic shifts.",
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          text: {
            type: Type.STRING,
            description: 'The analytical report text.',
          },
          sources: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                uri: { type: Type.STRING },
              },
              required: ["title", "uri"],
            },
          },
        },
        required: ["text", "sources"],
      },
    },
  });

  try {
    return JSON.parse(response.text || "{}");
  } catch (e) {
    return {
      text: "Global signals indicate a mass shift toward Minimalist Void aesthetics. Silhouette density is dropping as 'Zero Point' styling becomes the new authority standard.",
      sources: [{ title: "Neo Tokyo Market Feed", uri: "https://archives.closetkraze.nt/trends" }]
    };
  }
};

/**
 * Generates an outfit blueprint. Pro Image is used for high-fidelity requests.
 */
export const generateDreamOutfit = async (description: string, highFi: boolean = false) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = highFi ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

  const response = await ai.models.generateContent({
    model: model,
    contents: {
      parts: [{ text: `High-fashion editorial blueprint for Closet Kraze. Subject: ${description}. Technical streetwear, luxury avant-garde, cinematic lighting.` }],
    },
    config: {
      imageConfig: {
        aspectRatio: "3:4",
        imageSize: highFi ? "2K" : "1K"
      }
    }
  });

  const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
  if (part?.inlineData) {
    return `data:image/png;base64,${part.inlineData.data}`;
  }

  return "https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?auto=format&fit=crop&q=80&w=800";
};

/**
 * Connects to the Live Neural Concierge using Gemini 2.5 Flash Native Audio.
 */
export const connectToConcierge = (userContext: any, callbacks: any) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  return ai.live.connect({
    model: 'gemini-2.5-flash-native-audio-preview-12-2025',
    callbacks,
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
      },
      systemInstruction: `You are the Closet Kraze Neural Concierge. Clinical, elite, authoritative. 
      Handle: ${userContext.handle}. Rank: ${userContext.rankTier}. 
      Address the user as a peer or subordinate based on rank. Focus on acquisition speed and status acquisition.`,
    },
  });
};

