import React from 'react';
import { Product } from '../types';

interface ProductCardProps {
  product: Product;
  onClick: (product: Product) => void;
  onAddToCart: (product: Product) => void;
  onToggleWishlist: (product: Product) => void;
  isWishlisted: boolean;
}

const ProductCard: React.FC<ProductCardProps> = ({ 
  product, 
  onClick, 
  onAddToCart, 
  onToggleWishlist,
  isWishlisted 
}) => {
  const discountPercent = Math.round(((product.originalPrice - product.price) / product.originalPrice) * 100);
  const isHighHeat = product.hypeScore > 85;
  const demandWidth = Math.min(100, (product.viewers / 200) * 100);

  return (
    <div className="group relative flex flex-col h-full animate-in fade-in duration-700">
      <div 
        className="relative aspect-[4/5] overflow-hidden bg-zinc-950 border border-white/5 cursor-pointer mb-5 rounded-2xl shadow-2xl transition-all duration-500 group-hover:shadow-[0_0_60px_-15px_rgba(236,72,153,0.2)]"
        onClick={() => onClick(product)}
      >
        <img 
          src={product.image} alt={product.name} 
          className="w-full h-full object-cover transition-all duration-[1.5s] group-hover:scale-110 group-hover:opacity-40 group-hover:blur-[1px]"
        />

        {/* Kinetic Overlays */}
        {isHighHeat && (
          <div className="absolute inset-0 pointer-events-none opacity-20 bg-[radial-gradient(circle_at_center,_#EC4899_0%,_transparent_70%)] animate-pulse"></div>
        )}

        <div className="absolute top-0 left-0 p-5 z-10 flex flex-col gap-2">
          {product.isNew && (
            <div className="bg-blue-600 text-white px-3 py-1 text-[8px] font-black uppercase tracking-[0.2em] w-fit rounded-full shadow-lg">New Signal</div>
          )}
          {isHighHeat && (
            <div className="bg-[#EC4899] text-white px-3 py-1 text-[8px] font-black uppercase tracking-[0.2em] w-fit rounded-full shadow-lg animate-bounce">Surge Heat</div>
          )}
        </div>

        {discountPercent > 0 && (
          <div className="absolute top-0 right-0 p-5 z-10">
            <div className="bg-white text-black px-3 py-1 text-[9px] font-black uppercase tracking-widest rounded-full shadow-xl">-{discountPercent}%</div>
          </div>
        )}

        {/* Choice Hub */}
        <div className="absolute inset-0 flex flex-col items-center justify-center translate-y-8 opacity-0 group-hover:translate-y-0 group-hover:opacity-100 transition-all duration-500 p-10 bg-black/40 backdrop-blur-sm">
          <div className="flex w-full gap-3">
            <button 
              onClick={(e) => { e.stopPropagation(); onAddToCart(product); }}
              className="flex-1 py-5 bg-white text-black text-[10px] uppercase tracking-[0.4em] font-black hover:bg-[#EC4899] hover:text-white transition-all shadow-2xl active:scale-95 rounded-2xl"
            >
              Acquire
            </button>
            <button 
              onClick={(e) => { e.stopPropagation(); onToggleWishlist(product); }}
              className={`w-16 h-16 flex items-center justify-center rounded-2xl border transition-all ${
                isWishlisted ? 'bg-[#EC4899] border-[#EC4899] text-white' : 'bg-black/50 border-white/20 text-white hover:bg-white hover:text-black'
              }`}
            >
              {isWishlisted ? '💖' : '🤍'}
            </button>
          </div>
        </div>

        {product.stockCount <= 5 && (
          <div className="absolute bottom-5 left-5 right-5 z-10">
             <div className="w-full bg-red-600/90 backdrop-blur-md text-white py-2 px-4 text-[8px] font-black uppercase tracking-widest text-center rounded-xl shadow-2xl animate-pulse">
               Critical Inventory: {product.stockCount} LEFT
             </div>
          </div>
        )}
      </div>

      <div className="flex flex-col gap-3 flex-1" onClick={() => onClick(product)}>
        <div className="flex justify-between items-start">
          <div className="space-y-1">
            <h3 className="text-sm font-black uppercase tracking-tight text-white group-hover:text-[#EC4899] transition-colors leading-tight">{product.name}</h3>
            <span className="text-[8px] font-black text-zinc-600 uppercase tracking-widest">Sector_{product.category}</span>
          </div>
          <div className="text-right">
            <div className="text-lg font-black font-mono tracking-tighter text-white">GH₵{product.price}</div>
            <div className="text-[9px] font-mono text-zinc-600 line-through opacity-50 uppercase">GH₵{product.originalPrice}</div>
          </div>
        </div>

        <div className="space-y-1.5 pt-3 border-t border-white/5">
          <div className="flex justify-between items-center text-[7px] font-black uppercase tracking-[0.3em] text-zinc-600">
            <span>Neural Demand</span>
            <span className={isHighHeat ? 'text-[#EC4899]' : 'text-zinc-400'}>{demandWidth.toFixed(0)}% Active</span>
          </div>
          <div className="h-[3px] w-full bg-zinc-900 rounded-full overflow-hidden">
            <div 
              className={`h-full transition-all duration-[2s] ${isHighHeat ? 'bg-[#EC4899] shadow-[0_0_12px_#EC4899]' : 'bg-zinc-500'}`} 
              style={{ width: `${demandWidth}%` }}
            ></div>
          </div>
        </div>
      </div>
    </div>
  );
};

