import React, { useState, useEffect, useMemo } from 'react';
import Header from './components/Header';
import BottomNav from './components/BottomNav';
import ProductDetail from './components/ProductDetail';
import CartDrawer from './components/CartDrawer';
import NotificationCenter from './components/NotificationCenter';
import Lobby from './components/HomeLobby';
import FamousProducts from './components/FamousProducts';
import TryOn from './components/TryOn';
import Bundles from './components/Bundles';
import Categories from './components/Categories';
import FlashSales from './components/FlashSales';
import Profile from './components/Profile';
import WishlistView from './components/WishlistView';
import CategoryPanel from './components/CategoryPanel';
import SocialProofPopup from './components/SocialProofPopup';
import AdminPanel from './components/AdminPanel';
import SupplierDashboard from './components/SupplierDashboard';
import CheckoutView from './components/CheckoutView';
import AdminLogin from './components/AdminLogin';
import SupplierLogin from './components/SupplierLogin';
import RoleSelection from './components/RoleSelection';
import TrendIntelligence from './components/TrendIntelligence';
import ContactPanel from './components/ContactPanel';
import GameShowroom from './components/GameShowroom';
import PayForMe from './components/PayForMe';
import Tutorial from './components/Tutorial';
import LandingScreen from './components/LandingScreen';
import ConciergeLive from './components/ConciergeLive';
import { EXTENDED_PRODUCTS, MOCK_BUNDLES } from './mockData';
import { USER_ACHIEVEMENTS } from './data/extendedMock';
import { databaseService } from './services/databaseService';
import { getCurrentRank } from './data/rankingSystem';
import { Product, CartItem, Page, ViewState, UserStats, Achievement, Notification, PromoCode } from './types';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => localStorage.getItem('cc-auth-token') === 'true');

  // Changed: No longer automatically showing auth modal on landing
  const [showAuthModal, setShowAuthModal] = useState<boolean>(false);
  const [showTutorial, setShowTutorial] = useState<boolean>(false);
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.LOBBY);
  const [activeSupplierId, setActiveSupplierId] = useState<string | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => JSON.parse(localStorage.getItem('closet-kraze-cart') || '[]'));
  const [wishlist, setWishlist] = useState<string[]>(() => JSON.parse(localStorage.getItem('closet-kraze-wishlist') || '[]'));
  const [notifications, setNotifications] = useState<Notification[]>([]);

  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isNotificationOpen, setIsNotificationOpen] = useState(false);
  const [isCategoryPanelOpen, setIsCategoryPanelOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<any>('All');

  const [rep, setRep] = useState<number>(() => Number(localStorage.getItem('cc-user-rep') || '8500'));
  const [handle, setHandle] = useState<string>(() => localStorage.getItem('cc-user-handle') || 'Anonymous');
  const [activePromo, setActivePromo] = useState<PromoCode | null>(null);
  const [surgeTimerEnd, setSurgeTimerEnd] = useState<number | null>(() => Number(localStorage.getItem('cc-surge-timer') || '0') || null);

  const [stats, setStats] = useState<UserStats>(() => JSON.parse(localStorage.getItem('closet-kraze-stats') || '{"dailyGameAttempts":3,"lastGameReset":"2025-01-01","quests":[],"selectedPath":"CYBER","aiTryOnsUsedToday":0}'));

  // Live Activity Simulator
  const [activeUsers, setActiveUsers] = useState(1024);
  useEffect(() => {
    const interval = setInterval(() => {
      setActiveUsers(prev => prev + (Math.random() > 0.5 ? 1 : -1) * Math.floor(Math.random() * 5));
    }, 4000);
    return () => clearInterval(interval);
  }, []);

  const currentRank = useMemo(() => getCurrentRank(rep), [rep]);
  const balances = { coins: 4250, gems: 120, rep: rep };

  useEffect(() => {
    localStorage.setItem('closet-kraze-cart', JSON.stringify(cart));
    if (cart.length === 0) {
      setSurgeTimerEnd(null);
      localStorage.removeItem('cc-surge-timer');
    }
  }, [cart]);

  useEffect(() => {
    localStorage.setItem('cc-user-rep', rep.toString());
    localStorage.setItem('cc-user-handle', handle);
  }, [rep, handle]);

  useEffect(() => {
    setNotifications(databaseService.getGlobalNotifications());
  }, []);

  const addToCart = (product: Product, selectedSize?: string) => {
    // Action protected by auth
    if (!isAuthenticated) {
      setShowAuthModal(true);
      return;
    }

    if (!surgeTimerEnd) {
      const newEnd = Date.now() + (300 * 1000);
      setSurgeTimerEnd(newEnd);
      localStorage.setItem('cc-surge-timer', newEnd.toString());
    }
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id && item.selectedSize === selectedSize);
      if (existing) return prev.map(i => (i.id === product.id && i.selectedSize === selectedSize) ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1, selectedSize }];
    });
    setIsCartOpen(true);
  };

  const toggleWishlist = (product: Product) => {
    // Action protected by auth
    if (!isAuthenticated) {
      setShowAuthModal(true);
      return;
    }

    setWishlist(prev => {
      const updated = prev.includes(product.id) ? prev.filter(id => id !== product.id) : [...prev, product.id];
      localStorage.setItem('closet-kraze-wishlist', JSON.stringify(updated));
      return updated;
    });
  };

  const handleNavigateView = (view: ViewState) => {
    // Protect private views
    const protectedViews = [ViewState.PROFILE, ViewState.WISHLIST, ViewState.TRY_ON, ViewState.PAY_FOR_ME, ViewState.GAME_SHOWROOM];
    if (!isAuthenticated && protectedViews.includes(view)) {
      setShowAuthModal(true);
      return;
    }

    setCurrentView(view);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const renderView = () => {
    switch (currentView) {
      case ViewState.LOBBY:
        return <Lobby products={EXTENDED_PRODUCTS} stats={stats} wishlist={wishlist} onNavigate={handleNavigateView} onAddToCart={(id) => { const p = EXTENDED_PRODUCTS.find(x => x.id === id); if (p) addToCart(p, p.sizes?.[0]); }} onToggleWishlist={toggleWishlist} onProductClick={setSelectedProduct} onCompleteQuest={() => {}} />;
      case ViewState.FAMOUS:
        return <FamousProducts products={selectedCategory === 'All' ? EXTENDED_PRODUCTS : EXTENDED_PRODUCTS.filter(p => p.category === selectedCategory)} wishlist={wishlist} onProductClick={setSelectedProduct} onAddToCart={(p) => addToCart(p, p.sizes?.[0])} onToggleWishlist={toggleWishlist} />;
      case ViewState.TRY_ON: 
        return <TryOn rank={currentRank} stats={stats} onUsed={() => setStats(s => ({...s, aiTryOnsUsedToday: s.aiTryOnsUsedToday + 1}))} />;
      case ViewState.BUNDLES: 
        return <Bundles bundles={MOCK_BUNDLES} onAddBundle={(b) => b.products.forEach(p => addToCart(p, p.sizes?.[0]))} />;
      case ViewState.CATEGORIES: return <Categories onSelectCategory={setSelectedCategory} onNavigate={handleNavigateView} />;
      case ViewState.FLASH: return <FlashSales onAddToCart={(p) => addToCart(p, p.sizes?.[0])} />;
      case ViewState.PROFILE: return <Profile stats={stats} rep={rep} onNavigate={handleNavigateView} onLogout={() => { setIsAuthenticated(false); localStorage.removeItem('cc-auth-token'); setShowAuthModal(true); }} onApplyPromo={setActivePromo} activePromo={activePromo} />;
      case ViewState.WISHLIST: return <WishlistView products={EXTENDED_PRODUCTS} wishlistIds={wishlist} onAddToCart={(p) => addToCart(p, p.sizes?.[0])} onToggleWishlist={toggleWishlist} onProductClick={setSelectedProduct} onNavigate={handleNavigateView} rank={currentRank} />;
      case ViewState.TRENDS: return <TrendIntelligence stats={stats} />;
      case ViewState.CONTACT: return <ContactPanel />;
      case ViewState.GAME_SHOWROOM: return <GameShowroom attemptsRemaining={stats.dailyGameAttempts} onPlay={() => setStats(s => ({...s, dailyGameAttempts: s.dailyGameAttempts - 1}))} onWin={(r) => { setRep(prev => prev + 50); }} />;
      case ViewState.PAY_FOR_ME: return <PayForMe rank={currentRank} wishlistProducts={EXTENDED_PRODUCTS.filter(p => wishlist.includes(p.id))} onCompleteAcquisition={(p) => { setRep(r => r + 500); }} />;
      case ViewState.ADMIN_LOGIN: return <AdminLogin onSuccess={() => { setIsAuthenticated(true); setCurrentView(ViewState.ADMIN); }} onCancel={() => setCurrentView(ViewState.LOBBY)} />;
      case ViewState.SUPPLIER_LOGIN: return <SupplierLogin onSuccess={(id) => { setIsAuthenticated(true); setActiveSupplierId(id); setCurrentView(ViewState.SUPPLIER_DASHBOARD); }} onCancel={() => setCurrentView(ViewState.LOBBY)} />;
      case ViewState.ROLE_SELECTION: return <RoleSelection onSelect={(role) => setCurrentView(role === 'ADMIN' ? ViewState.ADMIN_LOGIN : ViewState.SUPPLIER_LOGIN)} onCancel={() => setCurrentView(ViewState.LOBBY)} />;
      case ViewState.ADMIN: return <AdminPanel onExit={() => setCurrentView(ViewState.LOBBY)} onNavigate={handleNavigateView} />;
      case ViewState.SUPPLIER_DASHBOARD: return <SupplierDashboard supplierId={activeSupplierId || 'sup1'} onLogout={() => setCurrentView(ViewState.LOBBY)} />;
      case ViewState.CHECKOUT: return <CheckoutView items={cart} onComplete={() => { setCart([]); setSurgeTimerEnd(null); setRep(prev => prev + 250); setCurrentView(ViewState.LOBBY); }} onCancel={() => setCurrentView(ViewState.LOBBY)} balances={balances} activePromo={activePromo} />;
      default: return <Lobby products={EXTENDED_PRODUCTS} stats={stats} wishlist={wishlist} onNavigate={handleNavigateView} onAddToCart={() => {}} onToggleWishlist={() => {}} onProductClick={setSelectedProduct} onCompleteQuest={() => {}} />;
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-[#FAFAFA] flex flex-col font-sans selection:bg-[#EC4899] selection:text-white">
      <Header 
        cartCount={cart.reduce((a, b) => a + b.quantity, 0)} 
        wishlistCount={wishlist.length}
        notificationCount={notifications.filter(n => !n.read).length}
        stats={stats}
        onCartOpen={() => setIsCartOpen(true)}
        onNotificationOpen={() => setIsNotificationOpen(true)}
        onNavigatePage={(p) => handleNavigateView(p === Page.HOME ? ViewState.LOBBY : ViewState.FAMOUS)}
        onNavigateView={handleNavigateView}
        currentPage={currentView === ViewState.LOBBY ? Page.HOME : Page.SHOP}
        currentView={currentView}
        dropTime={300}
        onOpenCategories={() => setIsCategoryPanelOpen(true)}
      />

      <div className="fixed top-20 left-0 right-0 h-1 bg-white/5 z-40">
         <div className="h-full bg-[#EC4899] shadow-[0_0_10px_#EC4899] transition-all duration-1000" style={{ width: `${(activeUsers / 1200) * 100}%` }}></div>
      </div>

      <main className="pt-24 flex-1">{renderView()}</main>

      <BottomNav currentView={currentView} onNavigate={handleNavigateView} onOpenCategories={() => setIsCategoryPanelOpen(true)} />

      <CartDrawer isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} items={cart} onRemove={(id) => setCart(prev => prev.filter(i => i.id !== id))} onUpdateQuantity={(id, d) => setCart(prev => prev.map(i => i.id === id ? {...i, quantity: Math.max(1, i.quantity + d)} : i))} onClear={() => setCart([])} onNavigate={handleNavigateView} surgeTimerEnd={surgeTimerEnd} activePromo={activePromo} rank={currentRank} />
      <NotificationCenter isOpen={isNotificationOpen} onClose={() => setIsNotificationOpen(false)} notifications={notifications} onMarkRead={(id) => setNotifications(prev => prev.map(n => n.id === id ? {...n, read: true} : n))} onMarkAllRead={() => setNotifications(prev => prev.map(n => ({...n, read: true})))} />
      <CategoryPanel isOpen={isCategoryPanelOpen} onClose={() => setIsCategoryPanelOpen(false)} onSelectCategory={setSelectedCategory} onNavigate={handleNavigateView} activeCategory={selectedCategory} products={EXTENDED_PRODUCTS} onProductSelect={setSelectedProduct} />
      <SocialProofPopup />

      {isAuthenticated && <ConciergeLive userContext={{ handle, rankTier: currentRank.tier, rep }} />}

      {selectedProduct && (
        <ProductDetail product={selectedProduct} stats={stats} allProducts={EXTENDED_PRODUCTS} onClose={() => setSelectedProduct(null)} onAddToCart={addToCart} onUpdateSynergy={() => {}} onToggleWishlist={toggleWishlist} onProductClick={setSelectedProduct} isInWishlist={wishlist.includes(selectedProduct.id)} rank={currentRank} />
      )}

      {showAuthModal && (
        <LandingScreen 
          onComplete={(arch, isNew) => { 
            setHandle('User_' + Math.floor(Math.random()*1000)); 
            setIsAuthenticated(true); 
            localStorage.setItem('cc-auth-token', 'true');
            setShowAuthModal(false); 
            if (isNew) setShowTutorial(true); 
          }} 
          onAdminAccess={() => { 
            setShowAuthModal(false); 
            setCurrentView(ViewState.ROLE_SELECTION); 
          }} 
          onClose={() => setShowAuthModal(false)} 
        />
      )}

      {showTutorial && <Tutorial onComplete={() => setShowTutorial(false)} onNavigate={handleNavigateView} />}

      {/* Global Activity Heartbeat */}
      <div className="fixed top-24 right-6 z-40 flex items-center gap-3 bg-black/40 backdrop-blur-md px-4 py-2 rounded-full border border-white/5 pointer-events-none">
        <div className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></div>
        <span className="text-[9px] font-black uppercase tracking-widest text-zinc-400">{activeUsers} Archivers Linked</span>
      </div>
    </div>
  );
};

export default App;

