  SUPPLIER_DASHBOARD = 'SUPPLIER_DASHBOARD',
  CHECKOUT = 'CHECKOUT',
  TRENDS = 'TRENDS',
  CONTACT = 'CONTACT',
  GAME_SHOWROOM = 'GAME_SHOWROOM',
  PAY_FOR_ME = 'PAY_FOR_ME'
}

export enum Page {
  HOME = 'HOME',
  SHOP = 'SHOP'
}

export interface Quest {
  id: string;
  title: string;
