  region: string;
  stockLevel: 'CRITICAL' | 'LOW' | 'STABLE';
  unitsLeft: number;
}

export interface ProductPerformance {
  productId: string;
  totalPurchases: number;
  totalSystemUsers: number;
  initialStock: number;
  hoursToSoldOut: number;
}

export interface Achievement {
