  const [newBroadcast, setNewBroadcast] = useState({ title: '', message: '', type: 'INFO' as Notification['type'] });
  const [isBroadcasting, setIsBroadcasting] = useState(false);
  const [broadcastLog, setBroadcastLog] = useState<Notification[]>([]);

  // Security State
  const [adminCreds, setAdminCreds] = useState({ identifier: '', password: '' });
  const [isUpdatingCreds, setIsUpdatingCreds] = useState(false);
  const [securityStatus, setSecurityStatus] = useState<string | null>(null);

  // State for product editing
