    e.preventDefault();
    const code: PromoCode = { ...newPromo, id: `promo_${Date.now()}`, code: newPromo.code.toUpperCase() };
    const updated = [code, ...promoCodes];
    setPromoCodes(updated);
    databaseService.savePromoCodes(updated);
    setNewPromo({ code: '', type: 'PERCENT', value: 0, description: '' });
