      <div className="relative z-10 w-full max-w-md animate-in slide-in-from-bottom-12 duration-700">
        {onClose && (
          <button 
            onClick={onClose}
            className="absolute -top-16 right-0 w-12 h-12 rounded-full glass flex items-center justify-center text-white hover:bg-white hover:text-black transition-all"
          >
            ✕
          </button>
        )}

        <div className="bg-[#0a0a0c]/80 backdrop-blur-3xl border border-white/5 rounded-[3rem] p-10 md:p-14 shadow-2xl shadow-black/50 overflow-hidden group">

          {/* Brand Header */}
