          {activeTab === 'SUPPLIERS' && <AdminSupplierPanel />}
        </main>
      </div>

      {isEditorOpen && (
        <AdminProductEditor 
          product={editingProduct}
          onSave={handleSaveProduct}
          onCancel={() => setIsEditorOpen(false)}
        />
      )}
    </div>
  );
};

