import React, { useState, useEffect } from 'react';
import { CartItem, ViewState, OrderStatus, PromoCode } from '../types';

interface CheckoutViewProps {
  items: CartItem[];
  onComplete: (orderDetails: any) => void;
  onCancel: () => void;
  balances: { coins: number; gems: number; rep: number };
  activePromo?: PromoCode | null;
}

const REGIONS = [
  { name: 'Greater Accra', cities: ['Accra', 'Tema', 'Madina', 'Adenta'] },
  { name: 'Ashanti', cities: ['Kumasi', 'Obuasi', 'Ejisu', 'Konongo'] },
  { name: 'Western', cities: ['Sekondi-Takoradi', 'Tarkwa', 'Axim'] },
  { name: 'Central', cities: ['Cape Coast', 'Winneba', 'Kasoa'] },
  { name: 'Eastern', cities: ['Koforidua', 'Nkawkaw', 'Nsawam'] },
  { name: 'Northern', cities: ['Tamale', 'Yendi', 'Savelugu'] }
];

const CheckoutView: React.FC<CheckoutViewProps> = ({ items, onComplete, onCancel, balances, activePromo }) => {
  const [step, setStep] = useState<'GEO_ZONING' | 'LOGISTICS' | 'PAYMENT' | 'PROCESSING' | 'SUCCESS'>('GEO_ZONING');
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    address: '',
    region: '',
    city: '',
    verificationPhrase: ''
  });

  const rawSubtotal = items.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const totalShipping = items.reduce((acc, item) => acc + ((item.shippingFee || 0) * item.quantity), 0);

  let subtotal = rawSubtotal;
  if (activePromo) {
    if (activePromo.type === 'PERCENT') {
      subtotal = subtotal * (1 - activePromo.value / 100);
    } else {
      subtotal = Math.max(0, subtotal - activePromo.value);
    }
  }

  const finalTotal = Math.floor(subtotal + totalShipping);
  const availableCities = REGIONS.find(r => r.name === formData.region)?.cities || [];

  const handleNextStep = (e: React.FormEvent) => {
    e.preventDefault();
    if (step === 'GEO_ZONING') setStep('LOGISTICS');
    else if (step === 'LOGISTICS') setStep('PAYMENT');
  };

  const handleFinalize = () => {
    if (!formData.verificationPhrase) {
      alert("Terminal Lock: Verification phrase required.");
      return;
    }
    setStep('PROCESSING');
    setTimeout(() => setStep('SUCCESS'), 3000);
  };

  if (step === 'PROCESSING') {
    return (
      <div className="fixed inset-0 z-[250] bg-black flex flex-col items-center justify-center p-10">
        <div className="w-20 h-20 border-4 border-[#EC4899]/20 border-t-[#EC4899] rounded-full animate-spin"></div>
        <h2 className="text-2xl font-serif italic text-white mt-8">Encrypting Transaction...</h2>
      </div>
    );
  }

  if (step === 'SUCCESS') {
    return (
      <div className="fixed inset-0 z-[250] bg-[#020202] flex flex-col items-center justify-center p-6 text-center">
        <h1 className="text-6xl font-serif italic text-white mb-6 tracking-tighter">Haul Secured.</h1>
        <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.5em] mb-12">Allocated to {formData.city}, {formData.region}</p>
        <button onClick={() => onComplete({ ...formData, items, total: finalTotal })} className="px-20 py-8 bg-white text-black rounded-full font-black uppercase tracking-widest text-xs hover:bg-[#EC4899] hover:text-white transition-all">Return to Circuit</button>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-[200] bg-[#020202] flex flex-col lg:flex-row animate-in fade-in duration-500 overflow-y-auto">
      <div className="w-full lg:w-2/5 bg-zinc-950 p-8 flex flex-col gap-8 border-l border-white/5 order-2 lg:order-2">
         <h2 className="text-3xl font-serif italic text-white">Acquisition Summary</h2>
         <div className="space-y-4">
            {items.map(item => (
              <div key={`${item.id}-${item.selectedSize}`} className="flex gap-4 items-center bg-black/40 p-4 rounded-2xl border border-white/5">
                 <img src={item.image} className="w-12 h-16 rounded-lg object-cover grayscale" />
                 <div className="flex-1">
                    <div className="text-[10px] font-black text-white uppercase truncate">{item.name}</div>
                    <div className="text-[8px] text-zinc-500 font-black uppercase">Qty: {item.quantity}</div>
                 </div>
                 <div className="text-xs font-mono font-black text-white">GH₵{item.price * item.quantity}</div>
              </div>
            ))}
         </div>
         <div className="pt-6 border-t border-white/5 space-y-4 text-right">
            <div className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">Total Valuation</div>
            <div className="text-5xl font-mono font-black text-white">GH₵{finalTotal}</div>
         </div>
      </div>

      <div className="w-full lg:w-3/5 p-8 lg:p-20 order-1 flex flex-col justify-center">
        <div className="max-w-xl mx-auto w-full space-y-12">
          <div className="flex items-center gap-4">
            {['GEO_ZONING', 'LOGISTICS', 'PAYMENT'].map((s, idx) => (
              <div key={s} className={`w-10 h-10 rounded-xl flex items-center justify-center text-xs font-black border transition-all ${step === s ? 'bg-white text-black' : 'bg-zinc-950 text-zinc-700 border-white/5'}`}>{idx + 1}</div>
            ))}
          </div>

          {step === 'GEO_ZONING' && (
            <form onSubmit={handleNextStep} className="space-y-8 animate-in slide-in-from-bottom-4">
               <h2 className="text-4xl font-serif italic text-white leading-none">Geographic Zoning</h2>
               <div className="space-y-6">
                  <div className="space-y-2">
                    <label className="text-[9px] font-black text-zinc-600 uppercase tracking-widest px-2">Regional Sector</label>
                    <select required value={formData.region} onChange={e => setFormData({...formData, region: e.target.value, city: ''})} className="w-full bg-zinc-950 border border-white/10 p-6 rounded-2xl text-xs font-black text-white outline-none">
                        <option value="" disabled>SELECT_REGION</option>
                        {REGIONS.map(r => <option key={r.name} value={r.name}>{r.name.toUpperCase()}</option>)}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[9px] font-black text-zinc-600 uppercase tracking-widest px-2">City Node</label>
                    <select required disabled={!formData.region} value={formData.city} onChange={e => setFormData({...formData, city: e.target.value})} className="w-full bg-zinc-950 border border-white/10 p-6 rounded-2xl text-xs font-black text-white outline-none disabled:opacity-20">
                        <option value="" disabled>SELECT_CITY</option>
                        {availableCities.map(c => <option key={c} value={c}>{c.toUpperCase()}</option>)}
                    </select>
                  </div>
               </div>
               <button type="submit" disabled={!formData.region || !formData.city} className="w-full py-6 bg-white text-black rounded-3xl font-black uppercase text-[10px] tracking-widest hover:bg-[#EC4899] hover:text-white transition-all">Confirm Zoning</button>
            </form>
          )}

          {step === 'LOGISTICS' && (
            <form onSubmit={handleNextStep} className="space-y-8 animate-in slide-in-from-bottom-4">
               <h2 className="text-4xl font-serif italic text-white leading-none">Logistics Protocol</h2>
               <div className="space-y-6">
                  <div className="space-y-2">
                    <label className="text-[9px] font-black text-zinc-600 uppercase tracking-widest px-2">Operator Identity</label>
                    <input type="text" required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full bg-zinc-950 border border-white/10 p-6 rounded-2xl text-xs font-black text-white outline-none" placeholder="NAME_STRING" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[9px] font-black text-zinc-600 uppercase tracking-widest px-2">Contact Uplink (Phone)</label>
                    <input type="tel" required value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full bg-zinc-950 border border-white/10 p-6 rounded-2xl text-xs font-black text-white outline-none" placeholder="+233 XX XXX XXXX" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[9px] font-black text-zinc-600 uppercase tracking-widest px-2">Coordinates</label>
                    <textarea required rows={2} value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} className="w-full bg-zinc-950 border border-white/10 p-6 rounded-2xl text-xs font-black text-white outline-none resize-none" placeholder="ADDRESS_STRING" />
                  </div>
               </div>
               <button type="submit" className="w-full py-6 bg-white text-black rounded-3xl font-black uppercase text-[10px] tracking-widest hover:bg-[#EC4899] hover:text-white transition-all">Validate Logistics</button>
            </form>
          )}

          {step === 'PAYMENT' && (
            <div className="space-y-8 animate-in slide-in-from-bottom-4">
               <h2 className="text-4xl font-serif italic text-white leading-none">Identity Handshake</h2>
               <div className="bg-zinc-950 border border-white/5 p-8 rounded-3xl space-y-4">
                  <div className="flex justify-between text-[10px] font-black uppercase text-zinc-600"><span>Target Node</span><span className="text-white">{formData.city}</span></div>
                  <div className="flex justify-between text-[10px] font-black uppercase text-zinc-600"><span>Authorized Valuation</span><span className="text-[#EC4899]">GH₵{finalTotal}</span></div>
                  <div className="pt-4 border-t border-white/5">
                    <label className="text-[9px] font-black text-zinc-600 uppercase tracking-widest block mb-2">Verification Security Phrase</label>
                    <input type="password" required value={formData.verificationPhrase} onChange={e => setFormData({...formData, verificationPhrase: e.target.value})} className="w-full bg-black border border-white/10 p-5 rounded-2xl text-xs font-black text-white outline-none" placeholder="••••••••••••" />
                  </div>
               </div>
               <button onClick={handleFinalize} className="w-full py-8 bg-[#EC4899] text-white rounded-[2rem] font-black uppercase text-xs tracking-[0.4em] hover:bg-white hover:text-[#EC4899] transition-all">Finalize Uplink Acquisition</button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

