import React, { useState, useEffect } from 'react';
import { CartItem, ViewState, OrderStatus, PromoCode } from '../types';

interface CheckoutViewProps {
  items: CartItem[];
  onComplete: (orderDetails: any) => void;
  onCancel: () => void;
  balances: { coins: number; gems: number; rep: number };
  activePromo?: PromoCode | null;
}

const REGIONS = [
  { id: 'accra', name: 'Greater Accra', icon: '🏛️', cities: ['Accra', 'Tema', 'Madina', 'Adenta'] },
  { id: 'ashanti', name: 'Ashanti', icon: '🏺', cities: ['Kumasi', 'Obuasi', 'Ejisu', 'Konongo'] },
  { id: 'western', name: 'Western', icon: '⚓', cities: ['Sekondi-Takoradi', 'Tarkwa', 'Axim'] },
  { id: 'central', name: 'Central', icon: '🏰', cities: ['Cape Coast', 'Winneba', 'Kasoa'] },
  { id: 'eastern', name: 'Eastern', icon: '⛰️', cities: ['Koforidua', 'Nkawkaw', 'Nsawam'] },
  { id: 'northern', name: 'Northern', icon: '🕌', cities: ['Tamale', 'Yendi', 'Savelugu'] }
];

const CheckoutView: React.FC<CheckoutViewProps> = ({ items, onComplete, onCancel, balances, activePromo }) => {
  const [step, setStep] = useState<'GEO_ZONING' | 'LOGISTICS' | 'PAYMENT' | 'PROCESSING' | 'SUCCESS'>('GEO_ZONING');
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    address: '',
    region: '',
    city: '',
    verificationPhrase: ''
  });

  const rawSubtotal = items.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const totalShipping = items.reduce((acc, item) => acc + ((item.shippingFee || 0) * item.quantity), 0);

  // Calculate Savings
  let promoDiscount = 0;
  if (activePromo) {
    if (activePromo.type === 'PERCENT') {
      promoDiscount = Math.floor(rawSubtotal * (activePromo.value / 100));
    } else {
      promoDiscount = Math.min(rawSubtotal, activePromo.value);
    }
  }

  const finalTotal = Math.floor(rawSubtotal - promoDiscount + totalShipping);
  const availableCities = REGIONS.find(r => r.name === formData.region)?.cities || [];

  const handleNextStep = (e: React.FormEvent) => {
    e.preventDefault();
    if (step === 'GEO_ZONING') setStep('LOGISTICS');
    else if (step === 'LOGISTICS') setStep('PAYMENT');
  };

  const handleFinalize = () => {
    if (!formData.verificationPhrase) {
      alert("Terminal Lock: Verification phrase required.");
      return;
    }
    setStep('PROCESSING');
    setTimeout(() => setStep('SUCCESS'), 3000);
  };

  if (step === 'PROCESSING') {
    return (
      <div className="fixed inset-0 z-[250] bg-black flex flex-col items-center justify-center p-10">
        <div className="relative">
          <div className="w-24 h-24 border-4 border-[#EC4899]/20 border-t-[#EC4899] rounded-full animate-spin"></div>
          <div className="absolute inset-0 flex items-center justify-center text-2xl">⚡</div>
        </div>
        <h2 className="text-3xl font-serif italic text-white mt-12 tracking-tighter uppercase">Encrypting Haul...</h2>
        <p className="text-[9px] font-black text-zinc-600 uppercase tracking-[0.5em] mt-4">Bypassing Regional Gateways</p>
      </div>
    );
  }

  if (step === 'SUCCESS') {
    return (
      <div className="fixed inset-0 z-[250] bg-[#020202] flex flex-col items-center justify-center p-6 text-center animate-in fade-in duration-1000">
        <div className="w-24 h-24 bg-green-500/10 border border-green-500/30 rounded-full flex items-center justify-center text-5xl mb-8 mx-auto shadow-[0_0_50px_rgba(34,197,94,0.2)]">✓</div>
        <h1 className="text-7xl font-serif italic text-white mb-6 tracking-tighter leading-none">Haul Secured.</h1>
        <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.5em] mb-16">Inventory allocated to Node_{formData.city.toUpperCase()}</p>
        <button onClick={() => onComplete({ ...formData, items, total: finalTotal })} className="px-20 py-8 bg-white text-black rounded-full font-black uppercase tracking-[0.3em] text-[10px] hover:bg-[#EC4899] hover:text-white transition-all shadow-3xl active:scale-95">Return to Circuit</button>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-[200] bg-[#020202] flex flex-col lg:flex-row animate-in fade-in duration-500 overflow-y-auto">
      {/* Commerce Panel (Sidebar) */}
      <div className="w-full lg:w-[400px] bg-zinc-950 p-8 flex flex-col gap-10 border-l border-white/5 order-2 lg:order-2 shrink-0">
         <div className="space-y-2">
            <h2 className="text-2xl font-serif italic text-white">Haul Analysis</h2>
            <div className="h-px w-10 bg-[#EC4899]"></div>
         </div>

         <div className="space-y-4 flex-1 overflow-y-auto pr-2 scrollbar-hide">
            {items.map(item => (
              <div key={`${item.id}-${item.selectedSize}`} className="flex gap-4 items-center bg-black/40 p-4 rounded-2xl border border-white/5 group hover:border-white/10 transition-all">
                 <div className="w-12 h-16 rounded-lg overflow-hidden grayscale group-hover:grayscale-0 transition-all">
                    <img src={item.image} className="w-full h-full object-cover" />
                 </div>
                 <div className="flex-1 min-w-0">
                    <div className="text-[9px] font-black text-white uppercase truncate">{item.name}</div>
                    <div className="text-[7px] text-zinc-600 font-black uppercase mt-1">Size: {item.selectedSize || 'OS'} // Qty: {item.quantity}</div>
                 </div>
                 <div className="text-[10px] font-mono font-black text-white whitespace-nowrap">GH₵{item.price * item.quantity}</div>
              </div>
            ))}
         </div>

         <div className="pt-8 border-t border-white/5 space-y-6">
            <div className="space-y-3">
               <div className="flex justify-between items-center text-[9px] font-black uppercase tracking-widest text-zinc-600">
                  <span>Gross Valuation</span>
                  <span className="text-zinc-400">GH₵{rawSubtotal}</span>
               </div>
               <div className="flex justify-between items-center text-[9px] font-black uppercase tracking-widest text-blue-500">
                  <span>Logistics Protocol</span>
                  <span>+ GH₵{totalShipping}</span>
               </div>
               {activePromo && (
                 <div className="flex justify-between items-center text-[9px] font-black uppercase tracking-widest text-green-500 animate-pulse">
                    <span>Promo Applied [{activePromo.code}]</span>
                    <span>- GH₵{promoDiscount}</span>
                 </div>
               )}
            </div>

            <div className="flex flex-col items-end">
               <span className="text-[10px] font-black text-[#EC4899] uppercase tracking-[0.5em] mb-1">Final Settlement</span>
               <div className="text-5xl font-mono font-black text-white tracking-tighter">GH₵{finalTotal}</div>
            </div>
         </div>
      </div>

      {/* Logic Panel (Main Flow) */}
      <div className="flex-1 p-8 lg:p-20 order-1 flex flex-col justify-center">
        <div className="max-w-2xl mx-auto w-full space-y-12">
          {/* Progress Indication */}
          <div className="flex items-center gap-6">
            {['GEO_ZONING', 'LOGISTICS', 'PAYMENT'].map((s, idx) => {
              const isActive = step === s;
              const isPast = ['LOGISTICS', 'PAYMENT', 'SUCCESS'].includes(step) && s === 'GEO_ZONING' || (step === 'PAYMENT' && s === 'LOGISTICS');
              return (
                <div key={s} className="flex items-center gap-6 flex-1 last:flex-none">
                  <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xs font-black border transition-all duration-500 ${isActive ? 'bg-white text-black border-white shadow-[0_0_30px_white/20]' : isPast ? 'bg-green-500/10 text-green-500 border-green-500/20' : 'bg-zinc-950 text-zinc-800 border-white/5'}`}>
                    {isPast ? '✓' : idx + 1}
                  </div>
                  {idx < 2 && <div className={`h-px flex-1 transition-all duration-700 ${isPast ? 'bg-green-500/30' : 'bg-zinc-900'}`}></div>}
                </div>
              );
            })}
          </div>

          {step === 'GEO_ZONING' && (
            <div className="space-y-10 animate-in slide-in-from-bottom-6 duration-700">
               <div className="space-y-3">
                  <h2 className="text-5xl font-serif italic text-white leading-none tracking-tighter">Regional Zoning</h2>
                  <p className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.4em]">Calibrate manufacturing node location</p>
               </div>

               <div className="space-y-8">
                  <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                    {REGIONS.map(r => {
                      const isSelected = formData.region === r.name;
                      return (
                        <button
                          key={r.id}
                          onClick={() => setFormData({...formData, region: r.name, city: ''})}
                          className={`p-6 rounded-[2rem] border transition-all duration-500 flex flex-col items-center gap-3 group ${isSelected ? 'bg-white border-white' : 'bg-zinc-950 border-white/5 hover:border-white/20'}`}
                        >
                          <span className={`text-3xl transition-transform group-hover:scale-110 ${isSelected ? 'grayscale-0' : 'grayscale opacity-40'}`}>{r.icon}</span>
                          <span className={`text-[10px] font-black uppercase tracking-widest ${isSelected ? 'text-black' : 'text-zinc-500'}`}>{r.name}</span>
                        </button>
                      );
                    })}
                  </div>

                  {formData.region && (
                    <div className="space-y-4 animate-in slide-in-from-top-4 duration-500">
                       <label className="text-[10px] font-black text-zinc-600 uppercase tracking-widest px-2">Sector City Node</label>
                       <div className="grid grid-cols-2 gap-3">
                          {availableCities.map(city => {
                            const isSelected = formData.city === city;
                            return (
                              <button
                                key={city}
                                onClick={() => setFormData({...formData, city})}
                                className={`py-4 px-6 rounded-2xl border transition-all duration-300 text-[10px] font-black uppercase tracking-widest ${isSelected ? 'bg-[#EC4899] border-[#EC4899] text-white shadow-[0_0_20px_rgba(236,72,153,0.3)]' : 'bg-black border-white/10 text-zinc-500 hover:border-white/30'}`}
                              >
                                {city}
                              </button>
                            );
                          })}
                       </div>
                    </div>
                  )}
               </div>

               <button 
                onClick={() => setStep('LOGISTICS')} 
                disabled={!formData.region || !formData.city} 
                className="w-full py-8 bg-white text-black rounded-[2.5rem] font-black uppercase text-[12px] tracking-[0.4em] hover:bg-[#EC4899] hover:text-white transition-all disabled:opacity-20 active:scale-95 shadow-2xl relative overflow-hidden group"
               >
                 <span className="relative z-10">Authorize Zone Link</span>
                 <div className="absolute inset-0 bg-[#EC4899] translate-y-full group-hover:translate-y-0 transition-transform duration-500"></div>
               </button>
            </div>
          )}

          {step === 'LOGISTICS' && (
            <form onSubmit={handleNextStep} className="space-y-10 animate-in slide-in-from-bottom-6 duration-700">
               <div className="space-y-3">
                  <h2 className="text-5xl font-serif italic text-white leading-none tracking-tighter">Logistics Protocol</h2>
