         </div>
         <div className="text-right">
            <span className="text-[8px] font-black text-zinc-800 uppercase tracking-widest block mb-1">Session Integrity</span>
            <div className="text-xs font-mono font-bold text-green-500 animate-pulse">● CONNECTION_OPTIMAL</div>
         </div>
